    sep = next(c for c in range(w) if all(grid[r][c] == grid[0][c] and grid[r][c] != 0 for r in range(h)))
    # ARC grids here use regularly spaced full separator rows/columns.
    col_seps = [c for c in range(w) if all(grid[r][c] == sep_color(grid) for r in range(h))]
    row_seps = [r for r in range(h) if all(v == sep_color(grid) for v in grid[r])]
    col_starts = [0] + [c + 1 for c in col_seps]
    row_starts = [0] + [r + 1 for r in row_seps]
    col_ends = col_seps + [w]
    row_ends = row_seps + [h]
    tile_h = row_ends[0] - row_starts[0]
    tile_w = col_ends[0] - col_starts[0]

    # The pattern is the non-background object in a tile other than the key tiles.
    bg = 0
    counts = {}
    for row in grid:
        for v in row:
            if v != sep_color(grid) and v != bg:
                counts[v] = counts.get(v, 0) + 1
    # Select the non-key pattern: generally the sole color in an otherwise empty tile.
    key_colors = set()
    for rs, re in zip(row_starts, row_ends):
        tile = [grid[r][col_starts[0]:col_ends[0]] for r in range(rs, re)]
        key_colors.update(v for row in tile for v in row if v != 0 and v != sep_color(grid))
    candidates = [v for v in counts if v not in key_colors]
    pattern_color = candidates[0]
    # Locate the isolated pattern tile and extract its binary mask.
    mask = None
    for rs, re in zip(row_starts, row_ends):
        for cs, ce in zip(col_starts, col_ends):
            tile = [grid[r][cs:ce] for r in range(rs, re)]
            if any(v == pattern_color for row in tile for v in row):
                mask = [[v == pattern_color for v in row] for row in tile]
                break
        if mask is not None:
            break

    out = [row[:] for row in grid]
    for band, (rs, re) in enumerate(zip(row_starts, row_ends)):
        # Each horizontal band takes its output color from the 2x2 key in the first tile.
        key_vals = [grid[r][c] for r in range(rs, re) for c in range(col_starts[0], col_ends[0]) if grid[r][c] not in (0, sep_color(grid))]
        color = key_vals[0]
        for cs, ce in zip(col_starts, col_ends):
            for dr in range(tile_h):
                for dc in range(tile_w):
