def sep_color(grid):
    # The separator color is the only nonzero color spanning a complete row and column.
    h, w = len(grid), len(grid[0])
    for r in range(h):
        v = grid[r][0]
        if v != 0 and all(x == v for x in grid[r]):
            return v
    for c in range(w):
        v = grid[0][c]
        if v != 0 and all(grid[r][c] == v for r in range(h)):
            return v
    raise ValueError("No full separator color found")
